/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it']
ips={i:re.search(r'ip address add ([\\d.]+)/',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,41)}
parents={z:('.' if '.' not in z else z.split('.',1)[1]) for z in zones if z"'!='"'.'}
index={z:i+1 for i,z in enumerate(zones)}
ns=lambda z: 'a.root-servers.' if z=='.' else 'ns.'+z+'.'
leaf=set(zones[15:20]+zones[21:])
for z,i in index.items():
 d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
 filename='db.root' if z=='.' else 'db.'+z
 (d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\nzone \"'+z+'\" { type master; file \"/etc/bind/'+filename+'\"; };\\n')
 lines=['"'$TTL 3600'"',f'@ IN SOA {ns(z)} hostmaster.{z if z "'!= "." else ""}'"'+('' if z=='.' else '.')+' ( 1 3600 900 604800 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
 if z in leaf: lines.append(f'@ IN A {ips[i]}')
 if z=='example.com': lines.append(f'www IN A {ips[6]}')
 if z in ('company.com','university.edu'): lines.extend(['@ IN MX 10 mail.'+z+'.',f'mail IN A {ips[i]}'])
 for child,parent in parents.items():
  if parent==z:
   lines.extend([f'{child}. IN NS {ns(child)}',f'{ns(child)} IN A {ips[index[child]]}'])
 (d/filename).write_text('\\n'.join(lines)+'\\n')
 with Path(f'pc{i}.startup').open('a') as f: f.write('\\nsystemctl restart named\\n')
d=Path('pc32/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
(d/'db.hints').write_text(f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
with Path('pc32.startup').open('a') as f: f.write('\\nsystemctl restart named\\n')
for i in range(33,41):
 with Path(f'pc{i}.startup').open('a') as f: f.write(f'\\necho \"nameserver {ips[32]}\" > /etc/resolv.conf\\n')
p=Path('lab.conf'); s=p.read_text()
for i in range(1,33): s=s.replace(f'pc{i}[image]=\"kathara/base\"',f'pc{i}[image]=\"kathara/bind\"')
p.write_text(s)
print('Configured',len(zones),'zones; resolver',ips[32],'; www',ips[6])
PY"

