/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import shutil,subprocess
zones=list(Path('.').glob('pc*/etc/bind/db.*'))
checkzone=shutil.which('named-checkzone'); checkconf=shutil.which('named-checkconf')
print('named-checkzone:',checkzone or 'non disponibile','named-checkconf:',checkconf or 'non disponibile')
errors=[]
for p in zones:
 if p.name=='db.hints': continue
 z='.' if p.name=='db.root' else p.name[3:]
 t=p.read_text()
 if '@ IN SOA ' not in t or '@ IN NS ' not in t: errors.append(str(p))
 if checkzone:
  x=subprocess.run([checkzone,z,str(p)],capture_output=True,text=True)
  if x.returncode: errors.append(x.stdout+x.stderr)
for p in Path('.').glob('pc*/etc/bind/named.conf'):
 if checkconf:
  x=subprocess.run([checkconf,str(p)],capture_output=True,text=True)
  if x.returncode: errors.append(x.stdout+x.stderr)
print('Zone verificate:',len(zones)-1,'errori:',len(errors))
for e in errors: print(e)
PY"

